#!/usr/bin/env bash
# skill-index.sh — Sága's sight over the crafts: one index of EVERY skill we
# hold, generated by walking the shelves, and read before any search.
#
# WHY THIS EXISTS. A skills-inventory existed and was dead: nothing generated
# it, nothing read it, and it pointed at a shelf that had moved. Two half
# mechanisms (an index no tool consumed, a finder blind to three layouts) wired
# to nothing. This replaces both with one loop:
#
#     walk every shelf  ->  write ONE machine-readable index  ->  skill-find
#     reads it first  ->  a session-start trigger refreshes it  ->  --check
#     FAILS LOUDLY when the index is missing a skill or has gone stale.
#
# The walk is GENERIC: it finds SKILL.md at any depth under a shelf, so a new
# developer's pack is seen the moment it lands, with no code change. That is
# the "auto-improving" half — the mechanism knows no pack by name.
#
# Shelves, in precedence order (a shipped skill wins a name collision on purpose):
#   1. .agents/skills/          ships with the repo + npm package
#   2. .agents/skills-local/    THIS MACHINE ONLY
#   3. $YMIR_HOME/.agents/skills/   the Allfather's own craft + imported packs
#   4. ~/.pi/agent/skills/      harness-wide, across projects
#
# Usage:
#   skill-index.sh              # regenerate the index + the human inventory
#   skill-index.sh --check      # fail if missing/stale/incomplete (exit 1)
#   skill-index.sh --print      # print the index path and counts
set -uo pipefail

_root() {
  local d; d="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  while [ "$d" != "/" ]; do
    [ -d "$d/.pi" ] && [ -d "$d/RULES" ] && { printf '%s' "$d"; return 0; }
    d="$(dirname "$d")"
  done
  printf '%s' "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
}
ROOT="$(_root)"

# The home is RESOLVED by the one resolver, never a literal path.
# shellcheck disable=SC1091
. "$ROOT/bin/vault/hoard-lib.sh" 2>/dev/null || true
if command -v ymir_home_root >/dev/null 2>&1; then ymir_home_root YMIR_HOME; fi
HOME_ROOT="${YMIR_HOME:-$ROOT}"

SHIPS="$ROOT/.agents/skills"
LOCALS="$ROOT/.agents/skills-local"
# The ships/local shelves belong to the CANONICAL checkout, not to whichever
# worktree happens to run this. The index is ONE shared file in the home; if each
# Yggdrasil worktree walked its own shipped skills and rewrote it, two worktrees
# would fight over it and a plain --check from one would call every canonical
# skill INCOMPLETE (found 2026-10-18). Resolve the common dir's parent instead.
_gd="$(git -C "$ROOT" rev-parse --git-common-dir 2>/dev/null || true)"
if [ -n "$_gd" ]; then
  case "$_gd" in /*) ;; *) _gd="$ROOT/$_gd" ;; esac
  _canon="$(cd "$(dirname "$_gd")" 2>/dev/null && pwd)" || _canon=""
  [ -n "$_canon" ] && [ -d "$_canon/.agents/skills" ] && { SHIPS="$_canon/.agents/skills"; LOCALS="$_canon/.agents/skills-local"; }
fi
HOMESKILLS="$HOME_ROOT/.agents/skills"
PISKILLS="$HOME/.pi/agent/skills"

# The index is private data (it names paths in the private home), so it lives in
# the home. The human inventory is the home's document shelf.
INDEX="$HOMESKILLS/skills.yaml"
INVENTORY="$HOME_ROOT/hodd/docs/skills-inventory.md"

mkdir -p "$(dirname "$INDEX")" 2>/dev/null || true
mkdir -p "$(dirname "$INVENTORY")" 2>/dev/null || true

# --- front matter extraction ------------------------------------------------
# ex <file> -> NAME<TAB>DESC, from frontmatter (name: / description:, incl. a
# folded > or | block). Falls back to the first heading, then to "(no desc)".
ex() {
  local f="$1" name="" desc="" line fold=""
  while IFS= read -r line; do
    if [ -z "$name" ] && [[ "$line" =~ ^name:[[:space:]]* ]]; then
      name="${line#*:}"; name="$(echo "$name" | sed 's/^[[:space:]]*//;s/^"//;s/"$//;s/^'"'"'//;s/'"'"'$//')"; continue
    fi
    if [ -z "$desc" ] && [[ "$line" =~ ^description:[[:space:]]* ]]; then
      desc="${line#*:}"; desc="$(echo "$desc" | sed 's/^[[:space:]]*//;s/^"//;s/"$//')"
      case "$desc" in
        ">"|">-"|"|"|"|-") desc=""; fold=1; continue ;;
      esac
      [ -n "$desc" ] && break
    fi
    if [ -z "$desc" ] && [ -n "$fold" ] && [[ "$line" =~ ^[[:space:]]*[^[:space:]#-] ]]; then
      desc="$(echo "$line" | sed 's/^[[:space:]]*//;s/"//g')"; break
    fi
  done < <(sed -n '1,20p' "$f" 2>/dev/null)
  [ -z "$name" ] && name="$(basename "$(dirname "$f")")"
  if [ -z "$desc" ]; then
    desc="$(grep -m1 '^#' "$f" 2>/dev/null | sed 's/^#*[[:space:]]*//' | cut -c1-160)"
  fi
  [ -z "$desc" ] && desc="(no description captured — unfindable; add a description: to the front matter)"
  desc="$(printf '%s' "$desc" | tr '\n\r' '  ' | sed 's/[[:space:]]\+/ /g; s/^ //; s/ $//')"
  printf '%s\t%s\n' "$name" "$desc"
}

# yaml_escape <text> -> a double-quoted-safe YAML scalar body
yaml_escape() { printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'; }

# _mtime <path> -> epoch seconds. GNU stat and BSD/macOS stat differ; PROBE, never
# assume (Rule 25). Empty when neither works, so a check degrades instead of lying.
_mtime() {
  stat -c %Y "$1" 2>/dev/null || stat -f %m "$1" 2>/dev/null || true
}

# --- the generic walk -------------------------------------------------------
# Every SKILL.md under a shelf, at any depth. No pack is known by name.
walk() {
  local shelf="$1"
  [ -d "$shelf" ] || return 0
  find "$shelf" -iname 'SKILL.md' \
    -not -path '*/.git/*' -not -path '*/node_modules/*' \
    -not -path '*/.yggdrasil/*' -not -path '*/dist/*' -not -path '*/build/*' \
    2>/dev/null | LC_ALL=C sort
}

# pack_of <shelf> <file> -> the first path segment under the shelf (the source)
pack_of() {
  local shelf="$1" f="$2" rel first
  rel="${f#"$shelf"/}"; first="${rel%%/*}"
  case "$rel" in
    */*) printf '%s' "$first" ;;
    *)   printf '%s' "." ;;
  esac
}

emit_rows() {  # shelf_id shelf_root -> "id\troot\tpack\tname\tpath\tdesc"
  local id="$1" root="$2" f pack r name desc
  [ -d "$root" ] || return 0
  while IFS= read -r f; do
    [ -n "$f" ] || continue
    pack="$(pack_of "$root" "$f")"
    r="$(ex "$f")"; name="${r%%$'\t'*}"; desc="${r#*$'\t'}"
    printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$id" "$root" "$pack" "$name" "$f" "$desc"
  done < <(walk "$root")
}

collect() {
  emit_rows ships  "$SHIPS"
  emit_rows local  "$LOCALS"
  emit_rows home   "$HOMESKILLS"
  emit_rows pi     "$PISKILLS"
}

# --- the human inventory ----------------------------------------------------
write_inventory() {
  local rows="$1" total
  total="$(printf '%s\n' "$rows" | grep -c . || true)"
  {
    printf '# Skills inventory — everything the Allfather'"'"'s world holds\n\n'
    printf -- '- **Generated:** %s · **Owner:** Brokk · **Generator:** `bin/agents/skill-index.sh` · **Machine index:** `$YMIR_HOME/.agents/skills/skills.yaml`\n' "$(date -Iseconds)"
    printf -- '- **This file is regenerated, never hand-edited.** The machine reads `skills.yaml`; this page is its human twin.\n'
    printf -- '- **Read the index first.** `bin/agents/skill-find.sh` reads it before grepping; a skill absent from it is a skill nobody finds.\n\n'
    printf -- '**Totals: %s skills across 4 shelves.**\n\n' "$total"
    local sid label
    for sid in ships local home pi; do
      case "$sid" in
        ships) label="Ships with Ymir (\`.agents/skills/\`)" ;;
        local) label="This machine only (\`.agents/skills-local/\`)" ;;
        home)  label="The home shelf — own craft + imported packs (\`\$YMIR_HOME/.agents/skills/\`)" ;;
        pi)    label="Harness-wide (\`~/.pi/agent/skills/\`)" ;;
      esac
      printf '## %s\n\n' "$label"
      printf '| Pack | Skill | What it does |\n|---|---|---|\n'
      printf '%s\n' "$rows" | awk -F'\t' -v s="$sid" '
        $1==s { d=$6; if (length(d)>150) d=substr(d,1,150);
                gsub(/\|/,"\\|",d); print "| `" $3 "` | `" $4 "` | " d " |" }'
      printf '\n'
    done
    printf -- '---\n_Generated by `bin/agents/skill-index.sh`. Do not edit by hand; edit the shelf and re-run._\n'
  } > "$INVENTORY"
}

# --- the machine index ------------------------------------------------------
write_index() {
  local rows="$1" total
  total="$(printf '%s\n' "$rows" | grep -c . || true)"
  {
    printf '# Sága'"'"'s skill index — GENERATED, do not edit by hand.\n'
    printf '# Generator: bin/agents/skill-index.sh   Read-first artifact for agents.\n'
    printf '# `path` is RELATIVE to the shelf root named by `shelf`, so the index is\n'
    printf '# portable: the reader anchors it to ITS OWN machine, and no machine path is\n'
    printf '# ever written here (Rule 25 — a path that exists on this box is not a path).\n'
    printf 'version: 2\n'
    printf 'generated: "%s"\n' "$(date -Iseconds)"
    printf 'total: %s\n' "$total"
    printf 'shelves:\n'
    printf '  - {id: ships, count: %s}\n' "$(printf '%s\n' "$rows" | awk -F'\t' '$1=="ships"' | grep -c . || true)"
    printf '  - {id: local, count: %s}\n' "$(printf '%s\n' "$rows" | awk -F'\t' '$1=="local"' | grep -c . || true)"
    printf '  - {id: home,  count: %s}\n' "$(printf '%s\n' "$rows" | awk -F'\t' '$1=="home"'  | grep -c . || true)"
    printf '  - {id: pi,    count: %s}\n' "$(printf '%s\n' "$rows" | awk -F'\t' '$1=="pi"'    | grep -c . || true)"
    printf 'skills:\n'
    printf '%s\n' "$rows" | while IFS=$'\t' read -r sid root pack name path desc; do
      [ -n "$sid" ] || continue
      printf '  - name: "%s"\n' "$(yaml_escape "$name")"
      printf '    shelf: %s\n' "$sid"
      printf '    pack: "%s"\n' "$(yaml_escape "$pack")"
      printf '    path: "%s"\n' "$(yaml_escape "${path#"$root"/}")"
      printf '    description: "%s"\n' "$(yaml_escape "$desc")"
    done
  } > "$INDEX"
}

# --- modes ------------------------------------------------------------------
case "${1:-}" in
  --check)
    # "Can't be just dead": the index must exist, be newer than the newest
    # SKILL.md on any shelf, and name every skill the live walk finds.
    fail=0
    if [ ! -s "$INDEX" ]; then
      printf 'STALE: no index at %s — run bin/agents/skill-index.sh\n' "$INDEX" >&2
      exit 1
    fi
    newest="$(collect | cut -f5 | while read -r p; do [ -f "$p" ] && _mtime "$p"; done | sort -n | tail -1)"
    idx_age="$(_mtime "$INDEX")"
    if [ -n "$newest" ] && [ "$newest" -gt "$idx_age" ]; then
      printf 'STALE: a SKILL.md is newer than the index (%s) — run bin/agents/skill-index.sh\n' "$INDEX" >&2
      fail=1
    fi
    missing=0
    while IFS=$'\t' read -r _sid _root _pack name path _desc; do
      [ -n "$path" ] || continue
      rel="${path#"$_root"/}"
      grep -q -- "path: \"$rel\"" "$INDEX" 2>/dev/null || { [ "$missing" -eq 0 ] && printf 'INCOMPLETE: skills present but absent from the index:\n' >&2; printf '  %s\n' "$rel" >&2; missing=$((missing+1)); fail=1; }
    done < <(collect)
    [ "$fail" = 0 ] && printf 'index fresh: %s skills\n' "$(grep -c '^  - name:' "$INDEX")"
    exit "$fail"
    ;;
  --print)
    printf '%s\n' "$INDEX"
    [ -s "$INDEX" ] && grep -m1 '^total:' "$INDEX"
    exit 0
    ;;
esac

ROWS="$(collect)"
write_index "$ROWS"
write_inventory "$ROWS"
printf 'index: %s\n' "$INDEX"
printf 'inventory: %s\n' "$INVENTORY"
printf 'total: %s skills\n' "$(printf '%s\n' "$ROWS" | grep -c . || true)"
